import{z as l,x as B,o as r,c as d,q as s,j as n,D as e,d as t,s as i,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"前向保密","description":"","frontmatter":{"title":"前向保密","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/forward-secrecy.md","filePath":"cs/forward-secrecy.md","lastUpdated":1791413859000}'),p={name:"cs/forward-secrecy.md"};function D(c,a,h,F,f,m){const A=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=s('<h1 id="前向保密" tabindex="-1">前向保密 <a class="header-anchor" href="#前向保密" aria-label="Permalink to &quot;前向保密&quot;">​</a></h1><div class="epigraph"><p>长期私钥将来泄漏，也不该能解开过去的会话。做法是每次用临时 DH，会话键用完即忘；静态 RSA 封装做不到这一点。</p><footer>—— Diffie, van Oorschot and Wiener, Authentication and Authenticated Key Exchanges, 1992；RFC 8446 对 (EC)DHE 的选择</footer></div><p>上一课<a href="/cs/key-management-hsm">密钥管理</a>保护长期根。缺口是<strong>根仍可能在某天泄漏</strong>（备份、强制、漏洞）。前向保密把历史会话从根的命运里摘出去。主干<a href="/cs/dh-vs-rsa">DH 与 RSA 分工</a>已点名；本课升为主题。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态 RSA 封装：谁拿到长期 \\(d\\)，谁解密所有被封过的 \\(k\\)。ECDHE：临时标量丢弃后，长期签钥只能伪造未来，不能回溯旧 AEAD 键。缺口是会话键的遗忘策略：内存、日志、核心转储都不要留下 \\(k\\)。</p><p><span class="marginnote">直觉类比：前向保密像每次谈话都临时约定一套一次性暗号，谈完立刻烧掉；日后哪怕有人偷走你的「母本」长期钥，也复原不了已经烧掉的暗号。静态 RSA 封装则像所有信件都用同一把锁——钥匙一丢，历史信件全部可读。</span></p><h3 id="_0-rtt-会打折" tabindex="-1">0-RTT 会打折 <a class="header-anchor" href="#_0-rtt-会打折" aria-label="Permalink to &quot;0-RTT 会打折&quot;">​</a></h3><p><a href="/cs/tls13-0rtt">TLS 1.3 0-RTT</a> 用 PSK 提前发数据，有重放与弱前向窗口。可用性与遗忘在此打架。</p><p><span class="marginnote">初学者容易以为「TLS 1.3 强制 PFS，所以 0-RTT 里的数据也享受完整前向保密」。实际上 0-RTT 数据由 PSK 派生，不在 ECDHE 的临时性保护里，攻击者还可以在重放窗口内把你首批请求原样重发——比如让「下单」被执行两次。</span></p><p><span class="marginnote">Diffie–van Oorschot–Wiener 的认证密钥交换讨论 PFS。本课不给「如何从服务器抠过去会话」的步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照静态封装 vs 临时 DH。要求：临时密钥在握手后清零；长期钥只做签名或认证。指出记录层序号防重放，但不等于 PFS。</p>',13)),(r(),n(o,null,{default:e(()=>[i(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20EPHEM%5B%22%E4%B8%B4%E6%97%B6%20ECDHE%22%5D%20--%3E%20SK%5B%22%E4%BC%9A%E8%AF%9D%E9%94%AE%22%5D%0A%20%20SK%20--%3E%20FORGET%5B%22%E7%94%A8%E5%90%8E%E6%B8%85%E9%9B%B6%22%5D%0A%20%20LONG%5B%22%E9%95%BF%E6%9C%9F%E7%AD%BE%E9%92%A5%22%5D%20--%3E%20AUTH%5B%22%E8%AE%A4%E8%AF%81%E6%8F%A1%E6%89%8B%22%5D%0A%20%20LONG%20-.-%3E%7C%22%E6%B3%84%E6%BC%8F%E4%B8%8D%E8%A7%A3%E5%AF%86%E8%BF%87%E5%8E%BB%22%7C%20SK%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"HSM 里的长期钥仍值得关；PFS 保证关不住的那一天历史仍在计算上保密。Signal 下一课把「多次会话」收成棘轮，使更细粒度的遗忘成为可能。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"为什么这一性质在今天格外重要：对手可以「先抓储、后解密」——今天把你的全部 TLS 流量原样录下来存着，等哪天拿到长期钥（漏洞、传票、内部人员）再翻旧账。有 PFS 时，「等」变得毫无意义，录下的密文永远是密文。")],-1)),(r(),n(o,null,{default:e(()=>[i(A,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E6%9F%90%E5%A4%A9%E9%95%BF%E6%9C%9F%E7%A7%81%E9%92%A5%E6%B3%84%E6%BC%8F%22%5D%20--%3E%20A%5B%22%E9%9D%99%E6%80%81%20RSA%20%E5%B0%81%E8%A3%85%E7%9A%84%E4%B8%96%E7%95%8C%22%5D%0A%20%20L%20--%3E%20B%5B%22ECDHE%20%2B%20%E9%81%97%E5%BF%98%E7%9A%84%E4%B8%96%E7%95%8C%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E5%BD%95%E4%B8%8B%E7%9A%84%E5%8E%86%E5%8F%B2%E6%B5%81%E9%87%8F%E5%8F%AF%E9%80%90%E6%9D%A1%E8%A7%A3%E5%AF%86%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E6%8D%9F%E5%A4%B1%3A%E8%BF%87%E5%8E%BB%E5%85%A8%E9%83%A8%2B%E6%9C%AA%E6%9D%A5%E5%8F%AF%E5%86%92%E5%85%85%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E5%90%84%E6%AC%A1%E4%BC%9A%E8%AF%9D%E7%9A%84%E4%B8%B4%E6%97%B6%20DH%20%E5%AF%86%E9%92%A5%E6%97%A9%E5%B7%B2%E6%B8%85%E9%9B%B6%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E5%8E%86%E5%8F%B2%E6%B5%81%E9%87%8F%E4%BB%8D%E8%AE%A1%E7%AE%97%E4%B8%8A%E4%BF%9D%E5%AF%86%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E6%8D%9F%E5%A4%B1%3A%E5%8F%AA%E5%89%A9%E6%9C%AA%E6%9D%A5(%E5%B0%BD%E5%BF%AB%E6%8D%A2%E9%92%A5)%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把后量子 KEM 提前展开。双棘轮下一课：每条消息都可以进一格，前向与后向保密的工程形态。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HSM 护根；PFS 让根的未来泄漏不回溯。</li><li>临时 DH + 遗忘会话键；静态 RSA 封装无此性质。</li><li>0-RTT 与日志里的 \\(k\\) 会削弱遗忘。</li><li>下一课 Signal 双棘轮。</li><li>出处：Diffie, van Oorschot and Wiener, 1992；RFC 8446。</li></ul>',4))])}const u=l(p,[["render",D]]);export{T as __pageData,u as default};
